namespace doris {

class Md5Digest {
public:
    Md5Digest();

    void update(const void* data, size_t length);
    void digest();

    const std::string& hex() const { return _hex; }

private:
    MD5_CTX _md5_ctx;
    std::string _hex;
};

} // namespace doris

