// Create a new Md5Digest instance; ready for immediate use per API contract.
doris::Md5Digest *md5 = new doris::Md5Digest();
// Track lifecycle/state: 0 = not finalized, 1 = finalized via digest().
FUZZ_SET_ATTR_INT(md5, "finalized", 0);
// Optional: track number of updates applied before finalization for coverage.
FUZZ_SET_ATTR_INT(md5, "updates", 0);

// Validation: Constructor has no preconditions; we mark state as not finalized for sequencing in later stubs.

// Enforce: update() must not be called after digest().
if (FUZZ_GET_ATTR_INT(md5, "finalized") != 0) { FUZZ_BAIL(); }

// Generate an ephemeral data buffer; does not escape this call.
std::string buf = FUZZ_PARAM_STR();
// Occasionally use zero-length updates to exercise that path.
size_t chosen_len = (*FUZZ_PARAM(unsigned int) % 2 == 0) ? static_cast<size_t>(0) : buf.size();
const void *data_ptr = buf.data();

// If length > 0, data_ptr must be valid for at least chosen_len bytes (buf.data() is valid).
// If length == 0, passing a non-null pointer is fine; many APIs ignore the pointer in that case.
md5->update(data_ptr, chosen_len);

// Update sequencing metadata for downstream stubs.
FUZZ_SET_ATTR_INT(md5, "updates", FUZZ_GET_ATTR_INT(md5, "updates") + 1);

// Validation: We guard against post-digest updates; data lifetime is scoped to this call only.

// Enforce single finalization per instance.
if (FUZZ_GET_ATTR_INT(md5, "finalized") != 0) { FUZZ_BAIL(); }

// Finalize the MD5 computation.
md5->digest();

// Mark as finalized for downstream sequencing.
FUZZ_SET_ATTR_INT(md5, "finalized", 1);

// Property: MD5 hex digest should be exactly 32 hex characters.
const std::string &h = md5->hex();
FUZZ_ASSERT(h.size() == 32, "MD5 hex length must be 32 after digest()");

// Validation: We prevent double-finalization and assert the invariant length of the resulting hex string.

// Enforce: hex() should be called only after digest().
if (FUZZ_GET_ATTR_INT(md5, "finalized") == 0) { FUZZ_BAIL(); }

// Retrieve the hex string and exercise it to keep it live.
const std::string &h = md5->hex();
// Assert known MD5 property: 32 ASCII hex characters.
FUZZ_ASSERT(h.size() == 32, "hex() must return 32 chars after digest()");
// Optionally touch a few characters to encourage coverage (no-op if empty due to assertion above).
volatile char c0 = h[0];
volatile char c1 = h[31];
(void)c0; (void)c1;

// Validation: We require prior digest() and assert the expected length of the digest string; object remains owned by fuzzer pool.
